'use client';

import { LayoutGroup } from 'motion/react';
import { useId } from 'react';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { AuthFrame, StepSwap } from './auth-frame';
import type { ProviderId } from './data';
import {
  CHECK_MS,
  INITIAL,
  LOOP_AFTER_MS,
  OPEN_MS,
  PROVIDER_MS,
  reducer,
  RESENT_MS,
  RESTING,
  SCRIPT,
  SEND_MS,
  workspaceOf,
  type AuthAction,
  type AuthState,
  type AuthStep,
} from './session';
import {
  CodeStep,
  DoneStep,
  OpeningStep,
  StartStep,
  WorkspaceStep,
} from './steps';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const HEADING = '[data-step-heading]';

/** A step that leaves stays in the page while it fades, ahead of the one that arrives: the last match is the one on screen. */
function lastOf(elements: NodeListOf<HTMLElement> | undefined) {
  if (!elements) {
    return null;
  }
  const lastIndex = elements.length - 1;
  return elements.item(lastIndex);
}

function pickedAt(state: AuthState, step: AuthStep) {
  if (state.step !== step) {
    return null;
  }
  return workspaceOf(state, state.pickedId) ?? null;
}

export default function Auth04() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const groupId = useId();
  const opening = pickedAt(state, 'opening');
  const entered = pickedAt(state, 'done');
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const matches = ref.current?.querySelectorAll<HTMLElement>(selector);
      const target = lastOf(matches);
      target?.focus();
    });
  }

  /** A person who moves to a new step lands on its title. */
  function actAndLand(action: AuthAction) {
    act(action);
    focusLater(HEADING);
  }

  function requestCode() {
    const after = reducer(state, { type: 'codeRequested' });
    act({ type: 'codeRequested' });
    if (!after.isSending) {
      focusLater('[data-email]');
      return;
    }
    schedule(() => actAndLand({ type: 'codeSent' }), SEND_MS);
  }

  function pressProvider(id: ProviderId) {
    act({ type: 'providerPressed', id });
    schedule(() => actAndLand({ type: 'providerReturned', id }), PROVIDER_MS);
  }

  /** The code is read only while it is checked, so the outcome is known when it is sent. */
  function submitCode() {
    const after = reducer(state, { type: 'codeSubmitted' });
    act({ type: 'codeSubmitted' });
    if (!after.isChecking) {
      focusLater('[data-code-slot="0"]');
      return;
    }
    const checked = reducer(after, { type: 'codeChecked' });
    const isIn = checked.step === 'workspace';
    schedule(() => {
      act({ type: 'codeChecked' });
      if (isIn) {
        focusLater(HEADING);
        return;
      }
      focusLater('[data-code-slot="0"]');
    }, CHECK_MS);
  }

  function resend() {
    act({ type: 'resendPressed' });
    schedule(() => act({ type: 'resendFaded' }), RESENT_MS);
  }

  function restartSignIn() {
    clearAll();
    actAndLand({ type: 'restarted' });
  }

  function openWhenReady() {
    schedule(() => actAndLand({ type: 'opened' }), OPEN_MS);
  }

  function pick(id: string) {
    actAndLand({ type: 'workspacePicked', id });
    openWhenReady();
  }

  function toggleCreate() {
    const wasOpen = state.isCreating;
    act({ type: 'createToggled' });
    if (wasOpen) {
      focusLater('[data-create-workspace]');
      return;
    }
    focusLater('[data-new-workspace]');
  }

  function create() {
    const after = reducer(state, { type: 'createSubmitted' });
    act({ type: 'createSubmitted' });
    if (after.step !== 'opening') {
      focusLater('[data-new-workspace]');
      return;
    }
    focusLater(HEADING);
    openWhenReady();
  }

  function switchWorkspace() {
    actAndLand({ type: 'switchPressed' });
  }

  /** A step on its way belongs to the round it was asked for in. */
  function replay() {
    clearAll();
    restart();
  }

  return (
    <ClockGate isActive={isInView}>
      <LayoutGroup id={groupId}>
        <AuthFrame
          ref={ref}
          aside={
            <ReplayButton
              isShown={canReplay}
              onReplay={replay}
              label='Replay'
            />
          }
          footer='Trouble signing in? A workspace admin can send you a new invitation.'
          announcer={<LiveRegion message={message} />}
        >
          <StepSwap stepKey={state.step}>
            {state.step === 'start' && (
              <StartStep
                state={state}
                pressed={pressed}
                onAction={act}
                onRequest={requestCode}
                onProvider={pressProvider}
              />
            )}
            {state.step === 'code' && (
              <CodeStep
                state={state}
                pressed={pressed}
                onAction={act}
                onSubmit={submitCode}
                onResend={resend}
                onRestart={restartSignIn}
              />
            )}
            {state.step === 'workspace' && (
              <WorkspaceStep
                state={state}
                pressed={pressed}
                onAction={act}
                onPick={pick}
                onToggleCreate={toggleCreate}
                onCreate={create}
                onRestart={restartSignIn}
              />
            )}
            {opening && <OpeningStep workspace={opening} />}
            {entered && (
              <DoneStep
                workspace={entered}
                account={state.account}
                onSwitch={switchWorkspace}
                onRestart={restartSignIn}
              />
            )}
          </StepSwap>
        </AuthFrame>
      </LayoutGroup>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { Fragment } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { BrandLogo } from '@/registry/ndeko/lib/brand-logos';
import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import {
  ChevronRightIcon,
  LoaderCircleIcon,
  MailIcon,
  PlusIcon,
  ShieldCheckIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { fadePresence, springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { Field, FieldLabel } from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import {
  OTPField,
  OTPFieldInput,
  OTPFieldSeparator,
} from '@/registry/ndeko/ui/otp-field';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import { CardHead, FieldProblem } from './auth-frame';
import {
  CODE_LENGTH,
  EMAIL_PLACEHOLDER,
  PERSON_NAME,
  PREVIEW_CODE_LABEL,
  PRODUCT_NAME,
  PROVIDERS,
  WORKSPACE_NAME_MAX_LENGTH,
  type Provider,
  type ProviderId,
  type Workspace,
} from './data';
import type { AuthAction, AuthState } from './session';

const SLOTS = Array.from({ length: CODE_LENGTH }, (_, index) => index);

const SEPARATOR_AFTER = 2;

const SEND_LABELS: Record<MorphState, string> = {
  idle: 'Email me a code',
  busy: 'Sending code',
  done: 'Code sent',
};

const SIGN_IN_LABELS: Record<MorphState, string> = {
  idle: 'Sign in',
  busy: 'Checking',
  done: 'Signed in',
};

const ROW = [
  'bg-foreground/[0.03] flex w-full cursor-pointer items-center gap-3 rounded-lg px-2.5 py-2 text-start outline-none',
  'transition-[background-color,scale] duration-150 ease-(--ease-out-strong) active:scale-[0.98]',
  'hover:bg-foreground/[0.06] focus-visible:ring-ring/25 focus-visible:ring-[3px]',
].join(' ');

function busyOf(isBusy: boolean): MorphState {
  if (isBusy) {
    return 'busy';
  }
  return 'idle';
}

function membersOf(count: number) {
  if (count === 1) {
    return '1 member';
  }
  return `${count} members`;
}

function slotLabelOf(index: number) {
  const position = index + 1;
  return `Digit ${position} of ${CODE_LENGTH}`;
}

function resendLabelOf(isResent: boolean) {
  if (isResent) {
    return 'New code sent';
  }
  return 'Send a new code';
}

function providerLabelOf(provider: Provider, isConnecting: boolean) {
  if (isConnecting) {
    return `Waiting for ${provider.name}`;
  }
  return `Continue with ${provider.name}`;
}

function MarkTile({ icon: TileIcon }: { icon: Icon }) {
  return (
    <span className='keycap-3d text-muted-foreground flex size-10 items-center justify-center rounded-lg'>
      <TileIcon className='size-5' />
    </span>
  );
}

type ProviderButtonProps = {
  provider: Provider;
  connecting: ProviderId | null;
  isLocked: boolean;
  isPressed: boolean;
  onPress: (id: ProviderId) => void;
};

function ProviderButton({
  provider,
  connecting,
  isLocked,
  isPressed,
  onPress,
}: ProviderButtonProps) {
  const isConnecting = connecting === provider.id;
  const label = providerLabelOf(provider, isConnecting);

  return (
    <Button
      type='button'
      variant='outline'
      size='lg'
      disabled={isLocked}
      focusableWhenDisabled
      onClick={() => onPress(provider.id)}
      className={cn('w-full', pressedQuietOf(isPressed))}
    >
      <AnimatedSize
        as='span'
        axis='width'
        contentClassName='relative flex items-center gap-2'
      >
        <Swap swapKey={String(isConnecting)}>
          {isConnecting && <LoaderCircleIcon className='animate-spin' />}
          {!isConnecting && <BrandLogo brand={provider.brand} />}
        </Swap>
        <Swap swapKey={label}>{label}</Swap>
      </AnimatedSize>
    </Button>
  );
}

type StartStepProps = {
  state: AuthState;
  pressed: string | null;
  onAction: (action: AuthAction) => void;
  onRequest: () => void;
  onProvider: (id: ProviderId) => void;
};

export function StartStep({
  state,
  pressed,
  onAction,
  onRequest,
  onProvider,
}: StartStepProps) {
  const isWaiting = state.connecting !== null;
  const isLocked = isWaiting || state.isSending;

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onRequest();
  }

  return (
    <>
      <CardHead
        mark={<MarkTile icon={MailIcon} />}
        title={`Sign in to ${PRODUCT_NAME}`}
      >
        One press with an account you already have, or a code by email. No
        password to remember.
      </CardHead>
      <div className='flex flex-col gap-2'>
        {PROVIDERS.map((provider) => (
          <ProviderButton
            key={provider.id}
            provider={provider}
            connecting={state.connecting}
            isLocked={isLocked}
            isPressed={pressed === `provider-${provider.id}`}
            onPress={onProvider}
          />
        ))}
      </div>
      <div className='text-muted-foreground flex items-center gap-3 text-xs'>
        <span aria-hidden='true' className='bg-border h-(--hairline) flex-1' />
        or with your email
        <span aria-hidden='true' className='bg-border h-(--hairline) flex-1' />
      </div>
      <form noValidate onSubmit={submit} className='flex flex-col gap-4'>
        <Field invalid={state.emailError !== null} className='gap-0'>
          <FieldLabel className='mb-1.5'>Work email</FieldLabel>
          <Input
            type='email'
            inputMode='email'
            autoComplete='email'
            data-email
            placeholder={EMAIL_PLACEHOLDER}
            value={state.email}
            readOnly={isLocked}
            onChange={(event) =>
              onAction({ type: 'emailTyped', value: event.target.value })
            }
          />
          <FieldProblem problem={state.emailError} />
        </Field>
        <MorphButton
          type='submit'
          size='lg'
          state={busyOf(state.isSending)}
          labels={SEND_LABELS}
          disabled={isWaiting}
          className={cn('w-full', pressedSolidOf(pressed === 'send'))}
        />
      </form>
    </>
  );
}

type CodeStepProps = {
  state: AuthState;
  pressed: string | null;
  onAction: (action: AuthAction) => void;
  onSubmit: () => void;
  onResend: () => void;
  onRestart: () => void;
};

export function CodeStep({
  state,
  pressed,
  onAction,
  onSubmit,
  onResend,
  onRestart,
}: CodeStepProps) {
  const email = state.email.trim();
  const resendLabel = resendLabelOf(state.isResent);

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit();
  }

  return (
    <>
      <CardHead
        mark={<MarkTile icon={ShieldCheckIcon} />}
        title='Check your email'
      >
        Enter the code sent to{' '}
        <span className='text-foreground font-medium break-all'>{email}</span>.{' '}
        <Button
          type='button'
          variant='link'
          onClick={onRestart}
          className='h-auto px-0 text-[13px]'
        >
          Use another email
        </Button>
      </CardHead>
      <form noValidate onSubmit={submit} className='flex flex-col gap-5'>
        <Field invalid={state.codeError !== null} className='gap-0'>
          <FieldLabel className='mb-1.5'>{`${CODE_LENGTH}-digit code`}</FieldLabel>
          <OTPField
            length={CODE_LENGTH}
            value={state.code}
            autoComplete='one-time-code'
            readOnly={state.isChecking}
            onValueChange={(value) => onAction({ type: 'codeTyped', value })}
            onValueComplete={onSubmit}
            className='gap-1.5 @md:gap-2'
          >
            {SLOTS.map((index) => (
              <Fragment key={index}>
                <OTPFieldInput
                  data-code-slot={index}
                  aria-label={slotLabelOf(index)}
                  className='@md:size-11'
                />
                {index === SEPARATOR_AFTER && <OTPFieldSeparator />}
              </Fragment>
            ))}
          </OTPField>
          <FieldProblem problem={state.codeError} />
        </Field>
        <p className='bg-foreground/[0.03] text-muted-foreground rounded-lg px-3 py-2 text-xs'>
          This preview sends no email. The code it accepts is{' '}
          <span className='text-foreground font-medium tabular-nums'>
            {PREVIEW_CODE_LABEL}
          </span>
        </p>
        <div className='flex flex-col-reverse gap-3 @sm:flex-row @sm:items-center @sm:justify-between'>
          <Button
            type='button'
            variant='ghost'
            size='sm'
            disabled={state.isResent}
            onClick={onResend}
            className='text-muted-foreground self-center @sm:self-auto'
          >
            <AnimatedSize
              as='span'
              axis='width'
              contentClassName='relative flex'
            >
              <Swap swapKey={resendLabel}>{resendLabel}</Swap>
            </AnimatedSize>
          </Button>
          <MorphButton
            type='submit'
            size='lg'
            state={busyOf(state.isChecking)}
            labels={SIGN_IN_LABELS}
            className={cn(
              'w-full @sm:w-auto',
              pressedSolidOf(pressed === 'sign-in')
            )}
          />
        </div>
      </form>
    </>
  );
}

type CreateRowProps = {
  state: AuthState;
  onAction: (action: AuthAction) => void;
  onToggle: () => void;
  onCreate: () => void;
};

/** An empty slot that invites an addition: a dashed row that opens into a name and Create. */
function CreateRow({ state, onAction, onToggle, onCreate }: CreateRowProps) {
  const fade = fadePresence();

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onCreate();
  }

  function closeOnEscape(event: React.KeyboardEvent<HTMLFormElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onToggle();
  }

  return (
    <AnimatePresence mode='popLayout' initial={false}>
      {!state.isCreating && (
        <motion.div key='row' {...fade}>
          <button
            type='button'
            data-create-workspace
            onClick={onToggle}
            className='hairline-border border-foreground/20 text-muted-foreground hover:text-foreground hover:bg-foreground/[0.03] focus-visible:ring-ring/25 flex w-full cursor-pointer items-center gap-3 rounded-lg border-dashed px-2.5 py-2 text-start text-[13px] transition-colors duration-150 outline-none focus-visible:ring-[3px]'
          >
            <span className='bg-foreground/[0.05] flex size-7 items-center justify-center rounded-md'>
              <PlusIcon className='size-4' />
            </span>
            Create workspace
          </button>
        </motion.div>
      )}
      {state.isCreating && (
        <motion.form
          key='form'
          noValidate
          onSubmit={submit}
          onKeyDown={closeOnEscape}
          className='bg-foreground/[0.03] flex flex-col gap-3 rounded-lg p-3'
          {...fade}
        >
          <Field invalid={state.newNameError !== null} className='gap-0'>
            <FieldLabel className='mb-1.5'>Workspace name</FieldLabel>
            <Input
              data-new-workspace
              autoComplete='organization'
              placeholder='Your team or company'
              maxLength={WORKSPACE_NAME_MAX_LENGTH}
              value={state.newName}
              onChange={(event) =>
                onAction({ type: 'newNameTyped', value: event.target.value })
              }
            />
            <FieldProblem problem={state.newNameError} />
          </Field>
          <div className='flex justify-end gap-2'>
            <Button type='button' variant='ghost' size='sm' onClick={onToggle}>
              Cancel
            </Button>
            <Button type='submit' size='sm'>
              Create and open
            </Button>
          </div>
        </motion.form>
      )}
    </AnimatePresence>
  );
}

type WorkspaceMarkProps = {
  workspace: Workspace;
  isLarge?: boolean;
};

function markClassOf(isLarge: boolean) {
  if (isLarge) {
    return 'size-14 rounded-xl';
  }
  return undefined;
}

/** The mark of the workspace travels from its row to the middle of the card when it opens. */
export function WorkspaceMark({
  workspace,
  isLarge = false,
}: WorkspaceMarkProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const travel = springOf(shouldReduceMotion);

  return (
    <motion.span
      layoutId={`mark-${workspace.id}`}
      layoutDependency={isLarge}
      transition={travel}
      className='flex shrink-0'
    >
      <CompanyMark
        seed={workspace.name}
        size='lg'
        className={markClassOf(isLarge)}
      />
    </motion.span>
  );
}

type WorkspaceStepProps = {
  state: AuthState;
  pressed: string | null;
  onAction: (action: AuthAction) => void;
  onPick: (id: string) => void;
  onToggleCreate: () => void;
  onCreate: () => void;
  onRestart: () => void;
};

export function WorkspaceStep({
  state,
  pressed,
  onAction,
  onPick,
  onToggleCreate,
  onCreate,
  onRestart,
}: WorkspaceStepProps) {
  return (
    <>
      <CardHead
        mark={<Avatar seed={PERSON_NAME} className='size-10' />}
        title='Pick a workspace'
      >
        Signed in as{' '}
        <span className='text-foreground font-medium break-all'>
          {state.account}
        </span>
        .{' '}
        <Button
          type='button'
          variant='link'
          onClick={onRestart}
          className='h-auto px-0 text-[13px]'
        >
          Not you?
        </Button>
      </CardHead>
      <div className='flex flex-col gap-1.5'>
        <ul aria-label='Your workspaces' className='flex flex-col gap-1.5'>
          {state.workspaces.map((workspace) => (
            <li key={workspace.id}>
              <button
                type='button'
                data-workspace={workspace.id}
                onClick={() => onPick(workspace.id)}
                className={cn(
                  ROW,
                  pressedQuietOf(pressed === `workspace-${workspace.id}`)
                )}
              >
                <WorkspaceMark workspace={workspace} />
                <span className='flex min-w-0 flex-1 flex-col'>
                  <span className='truncate text-[13px] font-medium'>
                    {workspace.name}
                  </span>
                  <span className='text-muted-foreground text-xs'>
                    {membersOf(workspace.members)}
                  </span>
                </span>
                <ChevronRightIcon className='text-muted-foreground size-4 shrink-0' />
              </button>
            </li>
          ))}
        </ul>
        <CreateRow
          state={state}
          onAction={onAction}
          onToggle={onToggleCreate}
          onCreate={onCreate}
        />
      </div>
    </>
  );
}

export function OpeningStep({ workspace }: { workspace: Workspace }) {
  return (
    <div className='flex flex-col items-center gap-4 py-4 text-center'>
      <WorkspaceMark workspace={workspace} isLarge />
      <div className='flex flex-col items-center gap-1.5'>
        <h1
          data-step-heading
          tabIndex={-1}
          className='flex items-center gap-2 text-xl font-semibold text-balance outline-none'
        >
          <LoaderCircleIcon className='text-muted-foreground size-5 shrink-0 animate-spin' />
          {`Opening ${workspace.name}`}
        </h1>
        <p className='text-muted-foreground text-[13px]'>
          Loading its projects and timesheets
        </p>
      </div>
    </div>
  );
}

type DoneStepProps = {
  workspace: Workspace;
  account: string;
  onSwitch: () => void;
  onRestart: () => void;
};

export function DoneStep({
  workspace,
  account,
  onSwitch,
  onRestart,
}: DoneStepProps) {
  return (
    <div className='flex flex-col items-center gap-5 py-2 text-center'>
      <span className='relative flex'>
        <WorkspaceMark workspace={workspace} isLarge />
        <StatusOrb
          tone='success'
          size='sm'
          className='absolute -end-2.5 -bottom-2.5'
        />
      </span>
      <div className='flex flex-col items-center gap-1.5'>
        <h1
          data-step-heading
          tabIndex={-1}
          className='text-xl font-semibold text-balance outline-none'
        >
          {`You are in ${workspace.name}`}
        </h1>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {`${membersOf(workspace.members)}. Signed in as `}
          <span className='text-foreground font-medium break-all'>
            {account}
          </span>
        </p>
      </div>
      <div className='flex flex-wrap justify-center gap-2'>
        <Button type='button' variant='outline' onClick={onSwitch}>
          Switch workspace
        </Button>
        <Button type='button' variant='ghost' onClick={onRestart}>
          Sign out
        </Button>
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion, type Variants } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { FieldError } from '@/registry/ndeko/ui/field';

import { PRODUCT_NAME } from './data';

const STEP_IN = { duration: 0.2, ease: EASE_OUT_STRONG };

const STEP_OUT = { duration: 0.15, ease: EASE_OUT_STRONG };

const STEP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)', transition: STEP_IN },
  exit: { opacity: 0, scale: 0.98, filter: 'blur(2px)', transition: STEP_OUT },
};

const PROBLEM_VARIANTS: Variants = {
  enter: { height: 0, opacity: 0 },
  visible: { height: 'auto', opacity: 1, transition: STEP_IN },
  exit: { height: 0, opacity: 0, transition: STEP_OUT },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: STEP_IN },
  exit: { opacity: 0, transition: STEP_OUT },
};

function stepVariantsOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return STEP_VARIANTS;
}

function problemVariantsOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return PROBLEM_VARIANTS;
}

